INSERT INTO `customer_birthday_logs` (`id`, `customer_id`, `sent_year`, `phone`, `message`, `sent_at`) VALUES
(1, 1697, 2026, '01141058632', 'كل عام وأنت بخير وبصحة وسعادة أستاذ/ة ياسين مصطفي 🎂🌹\r\nأسرة *حمزة للعطور* تتمنى لك عاماً سعيداً مليئاً بالبهجة والنجاح والبركة! ✨\r\n🎁 بهذه المناسبة السعيدة، يسعدنا أن نهديك خصم خاص 20% على أي زجاجة عطر من اختيارك عند زيارتك القادمة لنا! 🎉', '2026-10-06 14:20:07'),
(5, 1798, 2026, '01122548395', 'كل عام وأنت بخير وبصحة وسعادة  منه عمر 🎂🌹\r\nحمزه للعور حب يكون من اوائل الناس اللي بتهميك بعيك ميلادك  \r\nوحبين نبلغك ان اي فاتوره هتعملها خلال 24 ساعه هيكون ليك خصم محترم علي جميع احجام البرفيوم', '2026-10-06 21:07:26'),
(6, 406, 2026, '01110670001', 'كل عام وأنت بخير وبصحة وسعادة حسن اب الحسن 🎂🌹\r\nحمزه للعور حب يكون من اوائل الناس اللي بتهميك بعيك ميلادك  \r\nوحبين نبلغك ان اي فاتوره هتعملها خلال 24 ساعه هيكون ليك خصم محترم علي جميع احجام البرفيوم', '2026-10-08 11:07:37'),
(7, 8, 2026, '01152045729', 'كل عام وأنت بخير وبصحة وسعادة   مصطفى ابوسليم🎂🌹\r\nحمزه للعور حب يكون من اوائل الناس اللي بتهميك بعيك ميلادك  \r\nوحبين نبلغك ان اي فاتوره هتعملها خلال 24 ساعه هيكون ليك خصم محترم علي جميع احجام البرفيوم', '2026-10-08 11:08:16');
